-- Versioned checklist lengths preserve already-submitted 45/30-check audits.
insert into app_private.retail_audit_config(key,value) values('template_counts:2026-10-expanded-fsqa-v1','{"main":[6,13,8,6,6,6,4,11,4,4],"kiosk":[6,7,6,6,5,4,11,5,4]}') on conflict(key) do update set value=excluded.value;

do $change$ declare definition text; begin definition:=pg_get_functiondef('public.retail_audit_gateway(text,jsonb,text)'::regprocedure);if position($new$n integer; template_counts jsonb;$new$ in definition)=0 then definition:=replace(definition,$old$n integer;$old$,$new$n integer; template_counts jsonb;$new$);execute definition;end if;end $change$;
do $change$ declare definition text; begin definition:=pg_get_functiondef('public.retail_audit_gateway(text,jsonb,text)'::regprocedure);if position($new$v:=p_data->'payload';
  if coalesce(v->>'template_version','')<>'' then
   select value::jsonb->(p_data->>'audit_type') into template_counts from app_private.retail_audit_config where key='template_counts:'||(v->>'template_version');
   if template_counts is null then raise exception 'Unsupported audit template version';end if;
   select sum(value::integer)::integer into n from jsonb_array_elements_text(template_counts) q(value);
  else n:=case when p_data->>'audit_type'='main' then 45 when p_data->>'audit_type'='kiosk' then 30 else 0 end;end if;$new$ in definition)=0 then definition:=replace(definition,$old$v:=p_data->'payload'; n:=case when p_data->>'audit_type'='main' then 45 when p_data->>'audit_type'='kiosk' then 30 else 0 end;$old$,$new$v:=p_data->'payload';
  if coalesce(v->>'template_version','')<>'' then
   select value::jsonb->(p_data->>'audit_type') into template_counts from app_private.retail_audit_config where key='template_counts:'||(v->>'template_version');
   if template_counts is null then raise exception 'Unsupported audit template version';end if;
   select sum(value::integer)::integer into n from jsonb_array_elements_text(template_counts) q(value);
  else n:=case when p_data->>'audit_type'='main' then 45 when p_data->>'audit_type'='kiosk' then 30 else 0 end;end if;$new$);execute definition;end if;end $change$;
do $change$ declare definition text; begin definition:=pg_get_functiondef('public.retail_audit_gateway(text,jsonb,text)'::regprocedure);if position($new$  for x in select value from jsonb_array_elements(v->'items') loop
   if template_counts is not null and ((x->>'s')::integer<0 or (x->>'s')::integer>=jsonb_array_length(template_counts) or (x->>'i')::integer<0 or (x->>'i')::integer>=coalesce((template_counts->>((x->>'s')::integer))::integer,0)) then raise exception 'Invalid checkpoint for this audit template';end if;$new$ in definition)=0 then definition:=replace(definition,$old$  for x in select value from jsonb_array_elements(v->'items') loop$old$,$new$  for x in select value from jsonb_array_elements(v->'items') loop
   if template_counts is not null and ((x->>'s')::integer<0 or (x->>'s')::integer>=jsonb_array_length(template_counts) or (x->>'i')::integer<0 or (x->>'i')::integer>=coalesce((template_counts->>((x->>'s')::integer))::integer,0)) then raise exception 'Invalid checkpoint for this audit template';end if;$new$);execute definition;end if;end $change$;
do $change$ declare definition text; begin definition:=pg_get_functiondef('public.retail_audit_gateway(text,jsonb,text)'::regprocedure);if position($new$(coalesce((x->>'fsqa')::boolean,false) or upper(coalesce(x->>'section','')) ~ '(FOOD SAFETY|FSQA)')$new$ in definition)=0 then definition:=replace(definition,$old$upper(coalesce(x->>'section','')) like '%FOOD SAFETY%'$old$,$new$(coalesce((x->>'fsqa')::boolean,false) or upper(coalesce(x->>'section','')) ~ '(FOOD SAFETY|FSQA)')$new$);execute definition;end if;end $change$;
do $change$ declare definition text; begin definition:=pg_get_functiondef('public.retail_audit_gateway(text,jsonb,text)'::regprocedure);if position($new$not (coalesce((c.finding->>'fsqa')::boolean,false) or upper(coalesce(c.finding->>'section','')) ~ '(FOOD SAFETY|FSQA)')$new$ in definition)=0 then definition:=replace(definition,$old$upper(coalesce(c.finding->>'section','')) not like '%FOOD SAFETY%'$old$,$new$not (coalesce((c.finding->>'fsqa')::boolean,false) or upper(coalesce(c.finding->>'section','')) ~ '(FOOD SAFETY|FSQA)')$new$);execute definition;end if;end $change$;
do $change$ declare definition text; begin definition:=pg_get_functiondef('public.retail_audit_gateway(text,jsonb,text)'::regprocedure);if position($new$(coalesce((c.finding->>'fsqa')::boolean,false) or upper(coalesce(c.finding->>'section','')) ~ '(FOOD SAFETY|FSQA)')$new$ in definition)=0 then definition:=replace(definition,$old$upper(coalesce(c.finding->>'section','')) like '%FOOD SAFETY%'$old$,$new$(coalesce((c.finding->>'fsqa')::boolean,false) or upper(coalesce(c.finding->>'section','')) ~ '(FOOD SAFETY|FSQA)')$new$);execute definition;end if;end $change$;
